/*
# Seed DineBox Sample Data (fixed UUIDs)

Seeds 12 restaurants, 24 posts, 12 deals, menus, awards, reviews, rankings, and analytics.
Uses valid hex UUIDs for all records.
*/

ON CONFLICT (id) DO NOTHING;

-- 12 Restaurants
ON CONFLICT (id) DO NOTHING;

-- 24 Posts
ON CONFLICT (id) DO NOTHING;

-- 12 Deals
ON CONFLICT (id) DO NOTHING;

-- Menu Categories
ON CONFLICT (id) DO NOTHING;

-- Menu Items
ON CONFLICT DO NOTHING;

-- Awards
ON CONFLICT (id) DO NOTHING;

-- Reviews
ON CONFLICT (id) DO NOTHING;

-- Ranking Scores
ON CONFLICT DO NOTHING;

-- Analytics Events (sample for charts)
SELECT 'a1000000-0000-0000-0000-000000000001',
  CASE WHEN random() < 0.4 THEN 'profile_view' WHEN random() < 0.7 THEN 'post_view' WHEN random() < 0.85 THEN 'deal_view' ELSE 'follow' END,
  gen_random_uuid()::text, now() - (random() * interval '14 days')
FROM generate_series(1, 500) ON CONFLICT DO NOTHING;

SELECT 'a1000000-0000-0000-0000-000000000002',
  CASE WHEN random() < 0.4 THEN 'profile_view' WHEN random() < 0.7 THEN 'post_view' WHEN random() < 0.85 THEN 'deal_view' ELSE 'follow' END,
  gen_random_uuid()::text, now() - (random() * interval '14 days')
FROM generate_series(1, 400) ON CONFLICT DO NOTHING;

SELECT 'a1000000-0000-0000-0000-000000000003',
  CASE WHEN random() < 0.4 THEN 'profile_view' WHEN random() < 0.7 THEN 'post_view' WHEN random() < 0.85 THEN 'deal_view' ELSE 'follow' END,
  gen_random_uuid()::text, now() - (random() * interval '14 days')
FROM generate_series(1, 380) ON CONFLICT DO NOTHING;
