INSERT INTO restaurants (id, owner_id, name, slug, logo_url, cover_image_url, description, cuisine, address, location, postal_code, phone, website, instagram, facebook, opening_hours, rating, review_count, status, verified, featured, featured_at, opening_date, created_at) VALUES
('a1000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','Bella Napoli','bella-napoli','https://images.pexels.com/photos/674681/pexels-photo-674681.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/1437267/pexels-photo-1437267.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Authentic Neapolitan pizza and handmade pasta in the heart of Sembawang. Wood-fired oven, imported Italian ingredients, and a warm family atmosphere.','Italian','12 Jalan Tenteram, Sembawang','Sembawang','757708','+65 6758 1234','https://bellanapoli.sg','@bellanapoli.sg','bellanapolisg','{"mon":"11:30-22:00","tue":"11:30-22:00","wed":"11:30-22:00","thu":"11:30-22:00","fri":"11:30-23:00","sat":"11:30-23:00","sun":"11:30-22:00"}',4.8,247,'approved',true,true,now() - interval '5 days','2024-03-15',now() - interval '180 days'),
('a1000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001','Coffee Theory','coffee-theory','https://images.pexels.com/photos/302899/pexels-photo-302899.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/302899/pexels-photo-302899.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Third-wave specialty coffee and house-baked pastries. Single-origin beans, precision espresso, and a minimalist space designed for slow mornings.','Cafe','5 Ang Mo Kio Ave 10, #01-12','Ang Mo Kio','569726','+65 6451 8899','https://coffeetheory.sg','@coffeetheory.sg',null,'{"mon":"8:00-18:00","tue":"8:00-18:00","wed":"8:00-18:00","thu":"8:00-18:00","fri":"8:00-20:00","sat":"9:00-20:00","sun":"9:00-18:00"}',4.7,189,'approved',true,true,now() - interval '3 days','2024-06-01',now() - interval '120 days'),
('a1000000-0000-0000-0000-000000000003','a0000000-0000-0000-0000-000000000001','The Iron Steak','the-iron-steak','https://images.pexels.com/photos/675951/pexels-photo-675951.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/675951/pexels-photo-675951.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Dry-aged steaks grilled over Japanese binchotan. A carnivore''s paradise with a curated wine list and intimate counter seating.','Western','88 Yishun Central 1, #02-05','Yishun','768024','+65 6634 5678','https://theironteak.sg','@theironsteak.sg',null,'{"mon":"Closed","tue":"17:00-23:00","wed":"17:00-23:00","thu":"17:00-23:00","fri":"17:00-00:00","sat":"17:00-00:00","sun":"17:00-22:00"}',4.6,156,'approved',true,false,null,'2024-01-20',now() - interval '200 days'),
('a1000000-0000-0000-0000-000000000004','a0000000-0000-0000-0000-000000000001','Matcha Mood','matcha-mood','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Ceremonial-grade matcha drinks, matcha soft serve, and Japanese-inspired desserts. A serene green space for matcha lovers.','Japanese','231 Serangoon Central, #01-15 nex','Serangoon','556083','+65 6612 3344','https://matchamood.sg','@matchamood.sg',null,'{"mon":"10:00-22:00","tue":"10:00-22:00","wed":"10:00-22:00","thu":"10:00-22:00","fri":"10:00-22:30","sat":"10:00-22:30","sun":"10:00-22:00"}',4.5,132,'approved',false,false,null,'2024-08-10',now() - interval '90 days'),
('a1000000-0000-0000-0000-000000000005','a0000000-0000-0000-0000-000000000001','Sakura Sushi Bar','sakura-sushi-bar','https://images.pexels.com/photos/2098086/pexels-photo-2098086.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/2098086/pexels-photo-2098086.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Omakase-style sushi crafted by Tokyo-trained chefs. Seasonal fish flown in from Toyosu market. An intimate 8-seat counter experience.','Japanese','1 Orchard Boulevard, #02-12','Orchard','248649','+65 6733 8800','https://sakurasushi.sg','@sakurasushi.sg',null,'{"mon":"Closed","tue":"12:00-14:30, 18:00-22:00","wed":"12:00-14:30, 18:00-22:00","thu":"12:00-14:30, 18:00-22:00","fri":"12:00-14:30, 18:00-22:30","sat":"18:00-22:30","sun":"12:00-14:30, 18:00-22:00"}',4.9,98,'approved',true,false,null,'2023-11-05',now() - interval '300 days'),
('a1000000-0000-0000-0000-000000000006','a0000000-0000-0000-0000-000000000001','Hawker Heritage','hawker-heritage','https://images.pexels.com/photos/5409018/pexels-photo-5409018.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/5409018/pexels-photo-5409018.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Modern hawker stall celebrating Singapore''s hawker heritage. Char kway teow, Hainanese chicken rice, and laksa reimagined with respect for tradition.','Singaporean','20 Bedok South Road, #01-10','Bedok','469275','+65 6443 1122',null,'@hawkerheritage.sg',null,'{"mon":"10:00-21:00","tue":"10:00-21:00","wed":"10:00-21:00","thu":"10:00-21:00","fri":"10:00-22:00","sat":"10:00-22:00","sun":"10:00-21:00"}',4.4,312,'approved',false,false,null,'2024-02-14',now() - interval '160 days'),
('a1000000-0000-0000-0000-000000000007','a0000000-0000-0000-0000-000000000001','The Rooftop Bar','the-rooftop-bar','https://images.pexels.com/photos/3014019/pexels-photo-3014019.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/3014019/pexels-photo-3014019.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Skyline views, craft cocktails, and sunset vibes. Singapore''s most atmospheric rooftop bar with a 270-degree city panorama.','Bar','1 Raffles Place, #28-01 OUB Centre','Raffles Place','048616','+65 6538 7788','https://therooftop.sg','@therooftop.sg',null,'{"mon":"16:00-01:00","tue":"16:00-01:00","wed":"16:00-01:00","thu":"16:00-01:00","fri":"16:00-02:00","sat":"14:00-02:00","sun":"14:00-00:00"}',4.5,178,'approved',false,true,now() - interval '1 day','2024-04-20',now() - interval '140 days'),
('a1000000-0000-0000-0000-000000000008','a0000000-0000-0000-0000-000000000001','Modern Bowl','modern-bowl','https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Healthy grain bowls, poke, and smoothie bowls. Plant-forward, sustainable, and beautifully plated. Fuel for the modern urbanite.','Healthy','8 Marina Boulevard, #B2-32 Marina Bay Link Mall','Marina Bay','018981','+65 6622 4455','https://modernbowl.sg','@modernbowl.sg',null,'{"mon":"9:00-21:00","tue":"9:00-21:00","wed":"9:00-21:00","thu":"9:00-21:00","fri":"9:00-22:00","sat":"9:00-22:00","sun":"9:00-21:00"}',4.3,145,'approved',false,false,null,'2024-05-10',now() - interval '100 days'),
('a1000000-0000-0000-0000-000000000009','a0000000-0000-0000-0000-000000000001','Grain House','grain-house','https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Artisanal bakery and all-day brunch. Sourdough baked daily in-house, seasonal pastries, and locally roasted coffee.','Bakery','15 Tiong Bahru Road, #01-04','Tiong Bahru','161003','+65 6221 9988','https://grainhouse.sg','@grainhouse.sg',null,'{"mon":"8:00-18:00","tue":"8:00-18:00","wed":"8:00-18:00","thu":"8:00-18:00","fri":"8:00-20:00","sat":"8:00-20:00","sun":"8:00-18:00"}',4.6,203,'approved',false,false,null,'2023-09-15',now() - interval '320 days'),
('a1000000-0000-0000-0000-00000000000a','a0000000-0000-0000-0000-000000000001','Pasta Republic','pasta-republic','https://images.pexels.com/photos/1437267/pexels-photo-1437267.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/1487511/pexels-photo-1487511.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Fresh pasta made daily. A casual Italian trattoria serving classic and creative pasta dishes at honest prices.','Italian','501 Bukit Timah Road, #01-02','Bukit Timah','259760','+65 6738 2233','https://pastarepublic.sg','@pastarepublic.sg',null,'{"mon":"11:30-22:00","tue":"11:30-22:00","wed":"11:30-22:00","thu":"11:30-22:00","fri":"11:30-23:00","sat":"11:30-23:00","sun":"11:30-22:00"}',4.5,167,'approved',false,false,null,'2024-04-01',now() - interval '150 days'),
('a1000000-0000-0000-0000-00000000000b','a0000000-0000-0000-0000-000000000001','Little Bean','little-bean','https://images.pexels.com/photos/327090/pexels-photo-327090.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/327090/pexels-photo-327090.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','A cozy neighborhood cafe serving specialty coffee, brunch, and homemade cakes. Where every cup tells a story.','Cafe','34 East Coast Road, #01-08','East Coast','428754','+65 6345 6677','https://littlebean.sg','@littlebean.sg',null,'{"mon":"Closed","tue":"8:00-17:00","wed":"8:00-17:00","thu":"8:00-17:00","fri":"8:00-20:00","sat":"8:00-20:00","sun":"8:00-17:00"}',4.4,112,'approved',false,false,null,'2024-07-01',now() - interval '80 days'),
('a1000000-0000-0000-0000-00000000000c','a0000000-0000-0000-0000-000000000001','Smash Burger Co.','smash-burger-co','https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=200&h=200&fit=crop','https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=1200&h=600&fit=crop','Smashed-to-order burgers with caramelized edges, house sauce, and toasted brioche buns. The juiciest smash burgers in Singapore.','American','10 Jurong East Central 1, #01-20 JCube','Jurong East','609731','+65 6666 8899','https://smashburgersg.com','@smashburgersg',null,'{"mon":"11:00-22:00","tue":"11:00-22:00","wed":"11:00-22:00","thu":"11:00-22:00","fri":"11:00-23:00","sat":"11:00-23:00","sun":"11:00-22:00"}',4.3,234,'approved',false,false,null,'2024-09-01',now() - interval '60 days')
INSERT INTO posts (id, restaurant_id, type, title, description, image_url, cta_text, cta_url, status, published_at, created_at) VALUES
('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','new_dish','New Truffle Pasta','Our new truffle pasta has arrived. Fresh tagliatelle, imported Italian black truffle, and a 24-month aged parmesan cream sauce. Available for a limited time.','https://images.pexels.com/photos/1487511/pexels-photo-1487511.jpeg?auto=compress&cs=tinysrgb&w=800','View Menu','https://bellanapoli.sg/menu','published',now() - interval '2 hours',now() - interval '2 hours'),
('a2000000-0000-0000-0000-000000000002','a1000000-0000-0000-0000-000000000001','promotion','Weekend Pizza Festival','Every Friday to Sunday, enjoy unlimited wood-fired pizzas from our special weekend menu. $45 per person. Reservations recommended.','https://images.pexels.com/photos/708587/pexels-photo-708587.jpeg?auto=compress&cs=tinysrgb&w=800','Book a Table','https://bellanapoli.sg','published',now() - interval '1 day',now() - interval '1 day'),
('a2000000-0000-0000-0000-000000000003','a1000000-0000-0000-0000-000000000001','announcement','Now Open for Lunch Service','We are now serving lunch Tuesday through Sunday from 11:30am. Come enjoy our lunch specials and fresh pasta made daily.',null,null,null,'published',now() - interval '5 days',now() - interval '5 days'),
('a2000000-0000-0000-0000-000000000004','a1000000-0000-0000-0000-000000000002','new_dish','Matcha Cheesecake is Back','Our signature matcha cheesecake returns for a limited season. Made with ceremonial-grade Uji matcha and a buttery graham crust.','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '4 hours',now() - interval '4 hours'),
('a2000000-0000-0000-0000-000000000005','a1000000-0000-0000-0000-000000000002','event','Latte Art Throwdown','Join us Saturday night for our monthly latte art competition. Baristas from across Singapore compete. Free entry, $10 to vote.','https://images.pexels.com/photos/302899/pexels-photo-302899.jpeg?auto=compress&cs=tinysrgb&w=800','Register','https://coffeetheory.sg','published',now() - interval '2 days',now() - interval '2 days'),
('a2000000-0000-0000-0000-000000000006','a1000000-0000-0000-0000-000000000003','promotion','Weekend Steak Special','Every weekend: 300g dry-aged ribeye with truffle fries and a glass of Malbec for $88. Limited to 20 portions per night.','https://images.pexels.com/photos/675951/pexels-photo-675951.jpeg?auto=compress&cs=tinysrgb&w=800','Reserve','https://theironteak.sg','published',now() - interval '5 hours',now() - interval '5 hours'),
('a2000000-0000-0000-0000-000000000007','a1000000-0000-0000-0000-000000000003','new_menu','New A5 Wagyu Tasting Menu','Introducing our 7-course A5 Miyazaki Wagyu tasting menu. $280 per person. Available by reservation only, Wednesday through Sunday.','https://images.pexels.com/photos/3219547/pexels-photo-3219547.jpeg?auto=compress&cs=tinysrgb&w=800','Book Now','https://theironteak.sg','published',now() - interval '3 days',now() - interval '3 days'),
('a2000000-0000-0000-0000-000000000008','a1000000-0000-0000-0000-000000000004','new_dish','New Hojicha Soft Serve','Introducing our new hojicha soft serve. Roasted green tea from Kyoto, swirled with caramelized white chocolate flakes.','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '6 hours',now() - interval '6 hours'),
('a2000000-0000-0000-0000-000000000009','a1000000-0000-0000-0000-000000000004','collaboration','Pop-up with Tokyo Matcha Masters','We are hosting a 3-day pop-up with Tokyo''s legendary Matcha Masters. Exclusive drinks, limited merchandise, and tastings.','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=800','Learn More','https://matchamood.sg','published',now() - interval '1 day',now() - interval '1 day'),
('a2000000-0000-0000-0000-00000000000a','a1000000-0000-0000-0000-000000000005','new_menu','Autumn Omakase Menu','Our new autumn omakase menu features seasonal fish from Toyosu: Pacific saury, matsutake mushroom, and new harvest rice.','https://images.pexels.com/photos/2098086/pexels-photo-2098086.jpeg?auto=compress&cs=tinysrgb&w=800','Reserve','https://sakurasushi.sg','published',now() - interval '7 hours',now() - interval '7 hours'),
('a2000000-0000-0000-0000-00000000000b','a1000000-0000-0000-0000-000000000005','announcement','New Head Chef from Tokyo','We are honored to welcome Chef Yamamoto from Sushi Saito Tokyo. He brings 15 years of Edomae sushi tradition to Sakura.',null,null,null,'published',now() - interval '4 days',now() - interval '4 days'),
('a2000000-0000-0000-0000-00000000000c','a1000000-0000-0000-0000-000000000006','update','Renovation Complete','We are back and better than ever. Come see our refreshed space and enjoy our updated menu with new heritage dishes.','https://images.pexels.com/photos/5409018/pexels-photo-5409018.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '8 hours',now() - interval '8 hours'),
('a2000000-0000-0000-0000-00000000000d','a1000000-0000-0000-0000-000000000006','new_dish','Char Kway Teow with Fresh Cockles','We have sourced fresh cockles from Penang for our char kway teow. The wok hei is stronger than ever.','https://images.pexels.com/photos/5409018/pexels-photo-5409018.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '2 days',now() - interval '2 days'),
('a2000000-0000-0000-0000-00000000000e','a1000000-0000-0000-0000-000000000007','event','Sunset Sessions Live DJ','Every Friday, sunset DJ sets from 6pm. Cocktails, skyline views, and the best sunset in Singapore.','https://images.pexels.com/photos/3014019/pexels-photo-3014019.jpeg?auto=compress&cs=tinysrgb&w=800','Reserve','https://therooftop.sg','published',now() - interval '10 hours',now() - interval '10 hours'),
('a2000000-0000-0000-0000-00000000000f','a1000000-0000-0000-0000-000000000007','promotion','Golden Hour: 1-for-1 Cocktails','Daily 5-7pm, all cocktails are 1-for-1. Sip and watch the city turn gold.','https://images.pexels.com/photos/3014019/pexels-photo-3014019.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '3 days',now() - interval '3 days'),
('a2000000-0000-0000-0000-000000000010','a1000000-0000-0000-0000-000000000008','new_dish','New Acai Bowl','Our new acai bowl features organic acai from Brazil, fresh berries, and house-made granola. The perfect post-workout fuel.','https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '12 hours',now() - interval '12 hours'),
('a2000000-0000-0000-0000-000000000011','a1000000-0000-0000-0000-000000000008','announcement','Now Delivering Islandwide','We are now delivering across Singapore. Order through our website or your favorite delivery app.',null,'Order Now','https://modernbowl.sg','published',now() - interval '1 day',now() - interval '1 day'),
('a2000000-0000-0000-0000-000000000012','a1000000-0000-0000-0000-000000000009','new_dish','Sourdough Cinnamon Rolls','Fresh out of the oven every morning at 8am. Our sourdough cinnamon rolls are made with a 24-hour fermented dough.','https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '15 hours',now() - interval '15 hours'),
('a2000000-0000-0000-0000-000000000013','a1000000-0000-0000-0000-000000000009','event','Sourdough Workshop','Learn to bake sourdough at home. Our head baker walks you through the full process. $120 per person, includes starter.','https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=800','Sign Up','https://grainhouse.sg','published',now() - interval '2 days',now() - interval '2 days'),
('a2000000-0000-0000-0000-000000000014','a1000000-0000-0000-0000-00000000000a','new_menu','Truffle Season Menu','Truffle has arrived. Our seasonal truffle menu features 6 dishes with fresh black truffles from Umbria.','https://images.pexels.com/photos/1487511/pexels-photo-1487511.jpeg?auto=compress&cs=tinysrgb&w=800','View Menu','https://pastarepublic.sg','published',now() - interval '20 hours',now() - interval '20 hours'),
('a2000000-0000-0000-0000-000000000015','a1000000-0000-0000-0000-00000000000b','new_dish','New Pandan Cake','Our new pandan chiffon cake is made with fresh pandan leaves and coconut cream. A Singaporean classic, reimagined.','https://images.pexels.com/photos/327090/pexels-photo-327090.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '18 hours',now() - interval '18 hours'),
('a2000000-0000-0000-0000-000000000016','a1000000-0000-0000-0000-00000000000c','new_dish','The Triple Smash','Three patties, three slices of cheese, caramelized onions, and our house sauce. The biggest smash burger we have ever made.','https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '6 hours',now() - interval '6 hours'),
('a2000000-0000-0000-0000-000000000017','a1000000-0000-0000-0000-00000000000c','promotion','Student Meal Deal','Show your student ID and get a single smash burger, fries, and a drink for $9.90. Available weekdays 2-5pm.','https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=800',null,null,'published',now() - interval '1 day',now() - interval '1 day'),
('a2000000-0000-0000-0000-000000000018','a1000000-0000-0000-0000-00000000000c','announcement','New Outlet Opening in Punggol','We are opening our 3rd outlet in Punggol Digital District. Opening date to be announced soon.',null,null,null,'published',now() - interval '3 days',now() - interval '3 days')
INSERT INTO deals (id, restaurant_id, title, description, image_url, start_date, end_date, start_time, end_time, terms, status, created_at) VALUES
('a3000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','2-for-1 Pasta','Enjoy any two pasta dishes for the price of one. Choose from our full pasta menu including the new truffle pasta.','https://images.pexels.com/photos/1487511/pexels-photo-1487511.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '7 days','11:30','22:00','Valid for dine-in only. Not valid with other promotions. Limited to one redemption per table.','live',now() - interval '1 day'),
('a3000000-0000-0000-0000-000000000002','a1000000-0000-0000-0000-000000000002','$8 Lunch Set','Choose any coffee and any pastry from our daily selection for just $8. Available weekdays only.','https://images.pexels.com/photos/302899/pexels-photo-302899.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '5 days','12:00','14:00','Weekdays only. While stocks last. Dine-in only.','live',now() - interval '2 days'),
('a3000000-0000-0000-0000-000000000003','a1000000-0000-0000-0000-000000000003','Happy Hour 5-7PM','1-for-1 on all beers, wines, and house cocktails. Perfect for pre-dinner drinks.','https://images.pexels.com/photos/675951/pexels-photo-675951.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '10 days','17:00','19:00','Valid daily. Bar counter only. Not valid on eve of public holidays.','live',now() - interval '3 days'),
('a3000000-0000-0000-0000-000000000004','a1000000-0000-0000-0000-000000000004','Free Dessert with 2 Drinks','Order any two matcha drinks and get a free matcha soft serve.','https://images.pexels.com/photos/4109743/pexels-photo-4109743.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '14 days','10:00','22:00','One redemption per customer per visit. While stocks last.','live',now() - interval '1 day'),
('a3000000-0000-0000-0000-000000000005','a1000000-0000-0000-0000-000000000005','Omakase Early Bird 10% Off','Book 7 days in advance and enjoy 10% off our dinner omakase menu.','https://images.pexels.com/photos/2098086/pexels-photo-2098086.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '30 days','18:00','22:00','Must book at least 7 days in advance. Subject to availability. Not valid with other offers.','live',now() - interval '5 days'),
('a3000000-0000-0000-0000-000000000006','a1000000-0000-0000-0000-000000000006','Char Kway Teow + Drink $6.90','Our famous char kway teow with a free drink of your choice. The best deal in the hawker centre.','https://images.pexels.com/photos/5409018/pexels-photo-5409018.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '3 days','10:00','21:00','While stocks last. One per customer.','live',now() - interval '1 day'),
('a3000000-0000-0000-0000-000000000007','a1000000-0000-0000-0000-000000000007','Golden Hour 1-for-1 Cocktails','Daily 5-7pm, all cocktails are 1-for-1. Sip and watch the city turn gold.','https://images.pexels.com/photos/3014019/pexels-photo-3014019.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '14 days','17:00','19:00','Bar and terrace seating only. Not valid on public holidays.','live',now() - interval '2 days'),
('a3000000-0000-0000-0000-000000000008','a1000000-0000-0000-0000-000000000008','Build Your Own Bowl $12','Choose your base, protein, and 3 toppings for just $12. Regular price $16.','https://images.pexels.com/photos/1640777/pexels-photo-1640777.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '7 days','09:00','21:00','Valid for all bowl sizes. Dine-in and takeaway.','live',now() - interval '4 days'),
('a3000000-0000-0000-0000-000000000009','a1000000-0000-0000-0000-000000000009','Buy 5 Pastries Get 1 Free','Pick any 5 pastries from our daily selection and get the 6th free.','https://images.pexels.com/photos/1279330/pexels-photo-1279330.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '5 days','08:00','18:00','While stocks last. Same-day selection only.','live',now() - interval '1 day'),
('a3000000-0000-0000-0000-00000000000a','a1000000-0000-0000-0000-00000000000a','Truffle Pasta Tasting $35','A 3-course truffle pasta tasting menu for just $35. Regular price $55.','https://images.pexels.com/photos/1487511/pexels-photo-1487511.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '10 days','11:30','22:00','Valid for dine-in only. Limited time only.','live',now() - interval '3 days'),
('a3000000-0000-0000-0000-00000000000b','a1000000-0000-0000-0000-00000000000b','Weekend Brunch 15% Off','Enjoy 15% off our entire weekend brunch menu. Saturdays and Sundays only.','https://images.pexels.com/photos/327090/pexels-photo-327090.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '8 days','08:00','15:00','Weekends only. Dine-in only. Not valid with other promotions.','live',now() - interval '2 days'),
('a3000000-0000-0000-0000-00000000000c','a1000000-0000-0000-0000-00000000000c','Student Meal Deal $9.90','Single smash burger, fries, and a drink for $9.90. Show your student ID.','https://images.pexels.com/photos/1639557/pexels-photo-1639557.jpeg?auto=compress&cs=tinysrgb&w=800',CURRENT_DATE,CURRENT_DATE + interval '14 days','14:00','17:00','Weekdays 2-5pm only. Must show valid student ID. Dine-in only.','live',now() - interval '1 day')
