INSERT INTO reviews (id, restaurant_id, author_name, rating, text, dish_name, created_at) VALUES
('a6000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','Sarah',5,'Great pasta and really friendly service. The truffle pasta is absolutely worth the trip to Sembawang.','Truffle Pasta',now() - interval '3 days'),
('a6000000-0000-0000-0000-000000000002','a1000000-0000-0000-0000-000000000001','James',5,'Best Neapolitan pizza in Singapore. The Margherita is perfection.','Margherita',now() - interval '1 week'),
('a6000000-0000-0000-0000-000000000003','a1000000-0000-0000-0000-000000000001','Mei Ling',4,'Lovely atmosphere and authentic Italian food. A bit far but worth the visit.',null,now() - interval '2 weeks'),
('a6000000-0000-0000-0000-000000000004','a1000000-0000-0000-0000-000000000002','David',5,'The matcha cheesecake is incredible. Best coffee in Ang Mo Kio for sure.','Matcha Cheesecake',now() - interval '2 days'),
('a6000000-0000-0000-0000-000000000005','a1000000-0000-0000-0000-000000000002','Priya',5,'Beautiful space, excellent flat white. My go-to weekend spot.','Flat White',now() - interval '5 days'),
('a6000000-0000-0000-0000-000000000006','a1000000-0000-0000-0000-000000000003','Marcus',5,'The dry-aged ribeye is the best steak I''ve had in Singapore. Worth every dollar.','Dry-Aged Ribeye 300g',now() - interval '4 days'),
('a6000000-0000-0000-0000-000000000007','a1000000-0000-0000-0000-000000000003','Wendy',4,'Great food and intimate atmosphere. The wagyu tasting menu is exceptional.','A5 Wagyu Striploin 200g',now() - interval '10 days'),
('a6000000-0000-0000-0000-000000000008','a1000000-0000-0000-0000-000000000005','Tanaka',5,'Authentic Edomae sushi. Chef Yamamoto is a master. The otoro melts in your mouth.','Otoro Nigiri',now() - interval '1 week'),
('a6000000-0000-0000-0000-000000000009','a1000000-0000-0000-0000-000000000006','Aisha',5,'The char kway teow has the best wok hei in Singapore. A must-try.','Char Kway Teow',now() - interval '3 days'),
('a6000000-0000-0000-0000-00000000000a','a1000000-0000-0000-0000-000000000007','Kevin',5,'Best sunset views in Singapore. The cocktails are fantastic too.',null,now() - interval '1 week'),
('a6000000-0000-0000-0000-00000000000b','a1000000-0000-0000-0000-000000000009','Lina',5,'The sourdough is the best in Singapore. The cinnamon rolls sell out by 10am!','Sourdough Cinnamon Rolls',now() - interval '2 days'),
('a6000000-0000-0000-0000-00000000000c','a1000000-0000-0000-0000-00000000000c','Hafiz',4,'Juiciest smash burgers in the west. The triple is a challenge but so good.','The Triple Smash',now() - interval '4 days')
